#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>
#include <ArduinoOTA.h>
#include <DHT.h>
#include <Adafruit_Sensor.h>
#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>

#define DHTPIN 2
#define DHTTYPE DHT22

DHT dht(DHTPIN, DHTTYPE);

const char* ssid = "Burkia Studio";
const char* password = "Shooting";

const char* otaPassword = "12345678";

WebServer server(80);

BLECharacteristic* sensorCharacteristic;

#define SERVICE_UUID        "4fafc201-1fb5-459e-8fcc-c5c9c331914b"
#define CHARACTERISTIC_UUID "beb5483e-36e1-4688-b7f5-ea07361b26a8"

class CommandCallbacks : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic* characteristic) {
    String command = characteristic->getValue().c_str();

    Serial.print("BLE komut: ");
    Serial.println(command);

    if (command == "STATUS") {
      float humidity = dht.readHumidity();
      float temperature = dht.readTemperature();

      if (!isnan(humidity) && !isnan(temperature)) {
        String data = "Nem: " + String(humidity, 1) +
                      " % | Sicaklik: " + String(temperature, 1) + " C";

        sensorCharacteristic->setValue(data.c_str());
        sensorCharacteristic->notify();
      }
    }
  }
};

void setupBLE() {
  BLEDevice::init("ESP32_DHT22");

  BLEServer* serverBLE = BLEDevice::createServer();

  BLEService* service =
    serverBLE->createService(SERVICE_UUID);

  sensorCharacteristic =
    service->createCharacteristic(
      CHARACTERISTIC_UUID,
      BLECharacteristic::PROPERTY_READ |
      BLECharacteristic::PROPERTY_WRITE |
      BLECharacteristic::PROPERTY_NOTIFY
    );

  sensorCharacteristic->addDescriptor(new BLE2902());
  sensorCharacteristic->setCallbacks(new CommandCallbacks());

  sensorCharacteristic->setValue("ESP32 hazir");

  service->start();

  BLEAdvertising* advertising =
    BLEDevice::getAdvertising();

  advertising->addServiceUUID(SERVICE_UUID);
  advertising->setScanResponse(true);

  BLEDevice::startAdvertising();

  Serial.println("BLE hazir.");
}

