void setupWebServer() {

  server.on("/", HTTP_GET, []() {
    server.send(200, "text/html", otaPage);
  });

  server.on("/sensor", HTTP_GET, []() {
    server.send(200, "text/html", sensorPage());
  });

  server.on("/update", HTTP_POST,

    []() {
      bool success = !Update.hasError();

      server.send(
        200,
        "text/plain",
        success
          ? "Yukleme tamamlandi. ESP32 yeniden baslayacak."
          : "Yukleme hatasi!"
      );

      if (success) {
        delay(1000);
        ESP.restart();
      }
    },

    []() {

      HTTPUpload& upload = server.upload();

      if (upload.status == UPLOAD_FILE_START) {

        Serial.printf(
          "OTA basladi: %s\n",
          upload.filename.c_str()
        );

        if (!Update.begin(UPDATE_SIZE_UNKNOWN)) {
          Update.printError(Serial);
        }
      }

      else if (upload.status == UPLOAD_FILE_WRITE) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          ) != upload.currentSize
        ) {
          Update.printError(Serial);
        }
      }

      else if (upload.status == UPLOAD_FILE_END) {

        if (!Update.end(true)) {
          Update.printError(Serial);
        } else {
          Serial.printf(
            "OTA tamamlandi: %u bytes\n",
            upload.totalSize
          );
        }
      }
    }
  );

  server.begin();

  Serial.println("Web OTA hazir.");
}

void setupArduinoOTA() {

  ArduinoOTA.setHostname("ESP32_DHT22");

  ArduinoOTA.setPassword(otaPassword);

  ArduinoOTA.onStart([]() {
    Serial.println("ArduinoOTA basladi.");
  });

  ArduinoOTA.onEnd([]() {
    Serial.println("\nArduinoOTA tamamlandi.");
  });

  ArduinoOTA.onError([](ota_error_t error) {

    Serial.printf(
      "ArduinoOTA hata[%u]\n",
      error
    );
  });

  ArduinoOTA.begin();

  Serial.println("ArduinoOTA hazir.");
}

void setup() {

  Serial.begin(115200);

  dht.begin();

  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);

  Serial.print("Wi-Fi baglaniyor");

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println();
  Serial.println("Wi-Fi baglandi!");

  Serial.print("IP: ");
  Serial.println(WiFi.localIP());

  setupArduinoOTA();
  setupBLE();
  setupWebServer();

  Serial.println("Sistem hazir.");
}

void loop() {

  server.handleClient();

  ArduinoOTA.handle();

  static unsigned long lastRead = 0;

  if (millis() - lastRead >= 2000) {

    lastRead = millis();

    float humidity = dht.readHumidity();
    float temperature = dht.readTemperature();

    if (isnan(humidity) || isnan(temperature)) {

      Serial.println("DHT22 okunamadi!");

    } else {

      Serial.print("Nem: ");
      Serial.print(humidity);
      Serial.print(" % | Sicaklik: ");
      Serial.print(temperature);
      Serial.println(" C");

      String data =
        "Nem: " + String(humidity, 1) +
        " % | Sicaklik: " +
        String(temperature, 1) + " C";

      sensorCharacteristic->setValue(data.c_str());
      sensorCharacteristic->notify();
    }
  }
}
